function isMobileLayout() {
  return window.matchMedia("(max-width: 900px)").matches;
}
window.isMobileLayout = isMobileLayout;

function setMobileSidebarOpen(open) {
  if (!refs.sidebar || !refs.mobileSidebarBackdrop) return;
  refs.sidebar.classList.toggle("mobile-open", !!open);
  // Support both hidden class and visible class for smooth transitions
  refs.mobileSidebarBackdrop.classList.toggle("hidden", !open);
  refs.mobileSidebarBackdrop.classList.toggle("visible", !!open);
  document.body?.classList?.toggle("no-scroll", !!open);
  if (refs.mobileMenuBtn) {
    refs.mobileMenuBtn.setAttribute("aria-expanded", open ? "true" : "false");
  }
}
window.setMobileSidebarOpen = setMobileSidebarOpen;

window.navigateToModule = function(modName) {
  if (typeof window.isSaasModuleEnabled === 'function' && !window.isSaasModuleEnabled(modName)) {
    console.warn(`[Module Entitlement] Module '${modName}' is not enabled. Redirecting to dashboard.`);
    modName = 'dashboard';
  }
  isFormOpen = false;
  editRecordId = null;
  editStudentId = null;
  currentModule = modName;
  window.currentModule = modName;
  if (refs.searchInput) refs.searchInput.value = '';
  if (typeof isMobileLayout === 'function' && isMobileLayout()) setMobileSidebarOpen(false);
  renderAll();
  try {
    const items = document.querySelectorAll('.mobile-bottom-item[data-mod]');
    items.forEach(btn => btn.classList.toggle('active', btn.dataset.mod === modName));
  } catch (_) {}
  window.scrollTo({ top: 0, behavior: 'smooth' });
  const mainEl = document.querySelector('.main');
  if (mainEl) mainEl.scrollTop = 0;
};
window.switchModule = window.navigateToModule;

window.switchModuleFromMobile = function(modName) {
  window.navigateToModule(modName);
};

function toggleSidebarCollapse() {
  if (isMobileLayout()) {
    const opening = !refs.sidebar?.classList.contains("mobile-open");
    setMobileSidebarOpen(opening);
    return;
  }
  const appEl = document.querySelector(".app");
  const isCurrentlyCollapsed = refs.sidebar?.classList.contains("collapsed") || false;
  const willCollapse = !isCurrentlyCollapsed;

  refs.sidebar?.classList.toggle("collapsed", willCollapse);
  appEl?.classList.toggle("sidebar-collapsed", willCollapse);

  const sidebarToggleBtn = document.getElementById("sidebarToggleBtn");
  const topbarSidebarToggleBtn = document.getElementById("topbarSidebarToggleBtn");
  const tip = willCollapse ? "Expand sidebar (Ctrl+B)" : "Collapse sidebar (Ctrl+B)";
  if (sidebarToggleBtn) {
    sidebarToggleBtn.title = tip;
    sidebarToggleBtn.setAttribute("aria-label", tip);
  }
  if (topbarSidebarToggleBtn) {
    topbarSidebarToggleBtn.title = tip;
    topbarSidebarToggleBtn.setAttribute("aria-label", tip);
  }

  try {
    localStorage.setItem("tps_sidebar_collapsed", willCollapse ? "true" : "false");
  } catch (e) {}
}

function initSidebarCollapseState() {
  try {
    const saved = localStorage.getItem("tps_sidebar_collapsed");
    if (saved === "true" && !isMobileLayout()) {
      const appEl = document.querySelector(".app");
      refs.sidebar?.classList.add("collapsed");
      appEl?.classList.add("sidebar-collapsed");
      const sidebarToggleBtn = document.getElementById("sidebarToggleBtn");
      const topbarSidebarToggleBtn = document.getElementById("topbarSidebarToggleBtn");
      if (sidebarToggleBtn) {
        sidebarToggleBtn.title = "Expand sidebar (Ctrl+B)";
        sidebarToggleBtn.setAttribute("aria-label", "Expand sidebar (Ctrl+B)");
      }
      if (topbarSidebarToggleBtn) {
        topbarSidebarToggleBtn.title = "Expand sidebar (Ctrl+B)";
        topbarSidebarToggleBtn.setAttribute("aria-label", "Expand sidebar (Ctrl+B)");
      }
    }
  } catch (e) {}
}

function todayStr() {
  const d = new Date();
  return [d.getFullYear(), String(d.getMonth() + 1).padStart(2, '0'), String(d.getDate()).padStart(2, '0')].join('-');
}

function displayDate(iso) {
  if (!iso || typeof iso !== 'string') return "";
  const s = iso.trim().replace(/\//g, "-").replace(/\s+/g, "-");
  const parts = s.split("-");
  
  // Already DD-MM-YYYY
  if (parts.length === 3 && parts[2].length === 4) return s;
  
  // YYYY-MM-DD
  if (parts.length === 3 && parts[0].length === 4) {
    const [y, m, d] = parts;
    return `${d.padStart(2, '0')}-${m.padStart(2, '0')}-${y}`;
  }
  
  // MM-DD-YY or DD-MM-YY? Let's check. 
  // We'll assume the standard system format provides DD-MM-YYYY.
  // If it's a raw unformatted M/D/YY string like "4/17/26"
  if (parts.length === 3 && parts[2].length === 2) {
    // If the first part is > 12, it must be DD. 
    // If it's "4/17/26", the second part is 17 (>12), so it must be MM/DD/YY.
    let d, m, y;
    if (Number(parts[1]) > 12) {
      // MM/DD/YY
      m = parts[0];
      d = parts[1];
    } else {
      // DD/MM/YY
      d = parts[0];
      m = parts[1];
    }
    y = "20" + parts[2];
    return `${d.padStart(2, '0')}-${m.padStart(2, '0')}-${y}`;
  }

  return s; 
}

function normalizeToISO(str) {
  if (!str) return "";
  const s = String(str).trim().replace(/\//g, "-").replace(/\s+/g, "-");
  const parts = s.split("-");
  if (parts.length === 3) {
    if (parts[0].length === 4) return s.slice(0, 10); // already YYYY-MM-DD
    
    // Check if it's MM/DD/YY or DD/MM/YYYY
    let d, m, y;
    if (parts[2].length === 4) {
      // DD-MM-YYYY or MM-DD-YYYY
      if (Number(parts[0]) <= 12 && Number(parts[1]) > 12) {
         m = parts[0]; d = parts[1]; // M/D/YYYY
      } else {
         d = parts[0]; m = parts[1]; // D/M/YYYY
      }
      y = parts[2];
    } else if (parts[2].length === 2) {
      if (Number(parts[1]) > 12) {
        m = parts[0]; d = parts[1]; // M/D/YY
      } else {
        d = parts[0]; m = parts[1]; // D/M/YY
      }
      y = "20" + parts[2];
    }
    
    // Fallback if parsing didn't set vars
    if (!y) { d = parts[0]; m = parts[1]; y = parts[2]; }
    
    return `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  return s;
}

function nowStr() {
  return new Date().toISOString().slice(0, 19).replace("T", " ");
}

function timeStr() {
  // HH:mm (local time). Stored as TEXT in DB.
  return new Date().toTimeString().slice(0, 5);
}

