    admission_no: "Admission No",
    roll_no: "Roll No",
    last_active_at: "Last Active",
    last_login_at: "Last Login",
    device_os: "Device",
    targetAudience: "Target Audience",
    postedBy: "From / Posted By",
    targetType: "Audience Scope",
    targetClass: "Target Class",
