// UNIVERSAL POPUP-BLOCKED RESILIENT PRINT ENGINE
// ═══════════════════════════════════════════════════════════════════════
function openInPagePrintStudioModal(html, title) {
  let modal = document.getElementById("tpsPrintStudioModal");
  if (!modal) {
    modal = document.createElement("div");
    modal.id = "tpsPrintStudioModal";
    modal.style.cssText = "position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(15,23,42,0.85);backdrop-filter:blur(8px);z-index:999999;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:12px;box-sizing:border-box;";
    modal.innerHTML = `
      <div style="background:#ffffff;border-radius:16px;width:100%;max-width:1250px;height:95vh;display:flex;flex-direction:column;box-shadow:0 25px 50px -12px rgba(0,0,0,0.5);overflow:hidden;border:1px solid #cbd5e1;">
        <div style="display:flex;justify-content:space-between;align-items:center;padding:12px 20px;background:#0f172a;color:#ffffff;border-bottom:1px solid #334155;">
          <div style="display:flex;align-items:center;gap:10px;">
            <span class="material-symbols-outlined" style="font-size:24px;color:#60a5fa;">print</span>
            <div>
              <div id="tpsPrintStudioTitle" style="font-weight:800;font-size:1.05rem;color:#f8fafc;">Print Studio</div>
              <div style="font-size:0.72rem;color:#94a3b8;">Interactive Print Studio &amp; Document Viewer</div>
            </div>
          </div>
          <div style="display:flex;align-items:center;gap:10px;">
            <button id="tpsPrintStudioDirectPrintBtn" type="button" style="background:#2563eb;color:#ffffff;border:none;padding:8px 18px;border-radius:8px;font-weight:700;font-size:0.85rem;cursor:pointer;display:flex;align-items:center;gap:6px;box-shadow:0 2px 6px rgba(37,99,235,0.3);">
              <span class="material-symbols-outlined" style="font-size:18px;">print</span>
              <span>Print Now</span>
            </button>
            <button id="tpsPrintStudioNewTabBtn" type="button" style="background:#334155;color:#e2e8f0;border:1px solid #475569;padding:8px 14px;border-radius:8px;font-weight:600;font-size:0.82rem;cursor:pointer;display:flex;align-items:center;gap:6px;">
              <span class="material-symbols-outlined" style="font-size:18px;">open_in_new</span>
              <span>Open in Tab</span>
            </button>
            <button id="tpsPrintStudioCloseBtn" type="button" style="background:rgba(255,255,255,0.1);color:#ffffff;border:none;width:32px;height:32px;border-radius:50%;font-size:1.2rem;cursor:pointer;display:grid;place-items:center;">
              <span class="material-symbols-outlined" style="font-size:20px;">close</span>
            </button>
          </div>
        </div>
        <div style="flex:1;position:relative;background:#f8fafc;">
          <iframe id="tpsPrintStudioIframe" style="width:100%;height:100%;border:none;background:#ffffff;"></iframe>
        </div>
      </div>
    `;
    document.body.appendChild(modal);

    const closeBtn = document.getElementById("tpsPrintStudioCloseBtn");
    if (closeBtn) closeBtn.onclick = () => { modal.style.display = "none"; };
    modal.onclick = (e) => {
      if (e.target === modal) modal.style.display = "none";
    };
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && modal.style.display !== "none") {
        modal.style.display = "none";
      }
    });

    const printBtn = document.getElementById("tpsPrintStudioDirectPrintBtn");
    if (printBtn) {
      printBtn.onclick = () => {
        const ifr = document.getElementById("tpsPrintStudioIframe");
        if (ifr && ifr.contentWindow) {
          ifr.contentWindow.focus();
          ifr.contentWindow.print();
        }
      };
    }

    const newTabBtn = document.getElementById("tpsPrintStudioNewTabBtn");
    if (newTabBtn) {
      newTabBtn.onclick = () => {
        if (window._currentPrintStudioHtml) {
          const blob = new Blob([window._currentPrintStudioHtml], { type: "text/html;charset=utf-8" });
          const blobUrl = URL.createObjectURL(blob);
          const a = document.createElement("a");
          a.href = blobUrl;
          a.target = "_blank";
          a.rel = "noopener noreferrer";
          document.body.appendChild(a);
          a.click();
          setTimeout(() => {
            document.body.removeChild(a);
            URL.revokeObjectURL(blobUrl);
          }, 3000);
        }
      };
    }
  }

  window._currentPrintStudioHtml = html;
  const titleEl = document.getElementById("tpsPrintStudioTitle");
  if (titleEl) titleEl.textContent = title || "Print Studio";

  modal.style.display = "flex";

  const iframe = document.getElementById("tpsPrintStudioIframe");
  if (iframe) {
    const doc = iframe.contentWindow.document;
    doc.open();
    doc.write(html);
    doc.close();
  }
}

function openPrintWindowOrFallback(html, title = "Print Document", options = {}) {
  const { autoPrint = false, isInteractiveStudio = false } = options;

  let w = null;
  try {
    w = window.open("", "_blank");
  } catch (_) {
    w = null;
  }

  if (w && !w.closed) {
    try {
      w.document.open();
      w.document.write(html);
      w.document.close();
      w.focus();
      return;
    } catch (writeErr) {
      console.warn("Writing to popup failed, falling back to in-page printer:", writeErr);
    }
  }

  // If window.open was blocked by browser:
  if (isInteractiveStudio) {
    openInPagePrintStudioModal(html, title);
    if (typeof showToast === "function") {
      showToast("Opened Print Studio in preview modal", "info");
    }
    return;
  }

  // For non-interactive direct printable documents (Receipts, Slips, Reports):
  try {
    let iframe = document.getElementById("__tps_print_iframe__");
    if (!iframe) {
      iframe = document.createElement("iframe");
      iframe.id = "__tps_print_iframe__";
      iframe.style.position = "fixed";
      iframe.style.right = "0";
      iframe.style.bottom = "0";
      iframe.style.width = "0";
      iframe.style.height = "0";
      iframe.style.border = "none";
      iframe.style.visibility = "hidden";
      iframe.style.zIndex = "-9999";
      document.body.appendChild(iframe);
    }

    const doc = iframe.contentWindow.document;
    doc.open();
    doc.write(html);
    doc.close();

    if (typeof showToast === "function") {
      showToast("Opening print dialog…", "info");
    }

    setTimeout(() => {
      try {
        iframe.contentWindow.focus();
        iframe.contentWindow.print();
      } catch (printErr) {
        openInPagePrintStudioModal(html, title);
      }
    }, 450);
  } catch (err) {
    openInPagePrintStudioModal(html, title);
  }
}
window.openPrintWindowOrFallback = openPrintWindowOrFallback;
window.openInPagePrintStudioModal = openInPagePrintStudioModal;

function printStudentReport(student) {
  if (!student) return;
  const store = getStore();
  const split = splitClassName(student.className);
  const targetAdm = String(student.admissionNo || "").trim().toLowerCase();

  const exams = (store.exams || []).filter((e) => Boolean(targetAdm && String(e.admissionNo || e.registrationNo || "").trim().toLowerCase() === targetAdm));
  const fees = (store.fees || []).filter((f) => Boolean(targetAdm && String(f.admissionNo || "").trim().toLowerCase() === targetAdm));
  const attendance = (store.attendance || []).filter((a) => Boolean(targetAdm && String(a.admissionNo || "").trim().toLowerCase() === targetAdm));

    let grandObtained = 0;
  let grandMax = 0;
  exams.forEach((e) => {
      let marksArray = [];
      try { marksArray = JSON.parse(e.subjectMarks || "[]"); } catch(err){}
      let examObtained = 0;
      let examMax = 0;
      marksArray.forEach(m => {
          examObtained += asNum(m.total || m.obtained || m.theory);
          examMax += asNum(m.maxMarks || m.max || 100);
      });
      grandObtained += examObtained;
      grandMax += examMax;
  });
  const totalObtained = grandObtained;
  const totalMax = grandMax;
  const pct = totalMax > 0 ? Math.round((totalObtained / totalMax) * 1000) / 10 : 0;
  const result = pct >= 33 ? "Pass" : "Fail";

  const totalFee = fees.reduce((sum, f) => sum + asNum(f.totalFee), 0);
  const paidAmount = fees.reduce((sum, f) => sum + asNum(f.paidAmount), 0);
  const dueAmount = fees.reduce((sum, f) => sum + asNum(f.balance), 0);

  const uniqueDates = Array.from(new Set(attendance.map((a) => String(a.date)).filter(Boolean)));
  const presentUnique = Array.from(new Set(attendance.filter((a) => {
    const s = String(a.status || "").toLowerCase();
    return s.includes("present") || s.includes("late");
  }).map((a) => String(a.date))));
  const totalDays = uniqueDates.length;
  const presentDays = presentUnique.length;
  const attendancePct = totalDays > 0 ? Math.round((presentDays / totalDays) * 1000) / 10 : 0;

  const profileHtml = `
    <div class="id-header">
      <h1>Student Report</h1>
      <p>${student.fullName || ""} • Roll ${student.rollNo || ""} • Class ${split.classPart || ""}${split.sectionPart ? "-" + split.sectionPart : ""}</p>
    </div>
    <div class="box">
      <div class="row"><b>Date of Birth:</b> ${student.dob || "-"}</div>
      <div class="row"><b>Gender:</b> ${student.gender || "-"}</div>
      <div class="row"><b>Address:</b> ${student.address || "-"}</div>
      <div class="row"><b>Mobile:</b> ${student.phone || "-"}</div>
      <div class="row"><b>Father:</b> ${student.fatherName || "-"}</div>
    </div>
    <div class="id-grid">
      <div class="box"><b>Exams %:</b> ${pct}% • <b>Result:</b> ${result}</div>
      <div class="box"><b>Fees:</b> Paid ${paidAmount} • Due ${dueAmount}</div>
      <div class="box"><b>Attendance %:</b> ${attendancePct}%</div>
    </div>
  `;

  const examsHtml = (() => {
    if (!exams.length) return `<div class="box">No exam records.</div>`;
        const blocks = exams.map(e => {
        let marksArray = [];
        try { marksArray = JSON.parse(e.subjectMarks || "[]"); } catch(err){}
        const lines = marksArray.map(m => `<div class="row"><b>${m.subject}:</b> ${m.total || m.obtained || m.theory || "0"}/${m.maxMarks || m.max || "100"}</div>`).join("");
        return `<div class="box"><h2>${e.examName}</h2>${lines}</div>`;
    }).join("");
    return blocks;
  })();

  const feesHtml = (() => {
    if (!fees.length) return `<div class="box">No fee records.</div>`;
    const FEE_REPORT_TYPES = [
      { key: "tuitionFee",        label: "Tuition Fee",        icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">menu_book</span>' },
      { key: "transportFee",      label: "Transport Fee",      icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">directions_bus</span>' },
      { key: "admissionFormFee",  label: "Admission Form Fee",  icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">description</span>' },
      { key: "admissionFee",      label: "Admission Fee",      icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">school</span>' },
      { key: "computerFee",       label: "Computer Fee",       icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">computer</span>' },
      { key: "developmentFee",    label: "Development Fee",    icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">architecture</span>' },
      { key: "labFee",            label: "Lab Fee",            icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">science</span>' },
      { key: "sportsFee",         label: "Sports Fee",         icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">sports_soccer</span>' },
      { key: "libraryFee",        label: "Library Fee",        icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">local_library</span>' },
      { key: "examFee",           label: "Exam Fee",           icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">assignment</span>' },
      { key: "otherFee",          label: "Other Fee",          icon: '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">add_circle_outline</span>' },
    ];
    const blocks = fees
      .slice()
      .sort((a, b) => String(b.term).localeCompare(String(a.term)))
      .map((f) => {
        let feeDetails = "";
        let hasAny = false;
        FEE_REPORT_TYPES.forEach(({ key, label, icon }) => {
          const amt = parseFloat(f[key]) || 0;
          if (amt > 0) { hasAny = true; feeDetails += `<div class="row">${icon} ${label}: ₹${amt.toLocaleString("en-IN")}</div>`; }
        });
        if (!hasAny) {
          const labels = (f.feeTypes || f.monthlyFeeLabel || "").trim();
          const totalMonthly = parseFloat(f.monthlyFee) || 0;
          if (labels && totalMonthly > 0) {
            const parts = labels.split(",").map(s => s.trim()).filter(Boolean);
            const perPart = parts.length > 0 ? totalMonthly / parts.length : 0;
            parts.forEach(part => { feeDetails += `<div class="row"><span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;margin-right:4px;">payments</span> ${part}: ₹${perPart.toLocaleString("en-IN")}</div>`; });
          } else if (labels) {
            feeDetails += `<div class="row">Fee Types: ${labels}</div>`;
          }
        }
        return `
        <div class="box">
          <h2>Term: <span style="cursor:help;border-bottom:1.5px dotted #94a3b8;" title="${window.safeEscapeAttr ? window.safeEscapeAttr(window.buildTermBreakdownTooltip(f, 'term', f.term)) : ''}">${window.formatTermString(f.term) || ""}</span> — RCP-${f.id}</h2>
          ${feeDetails || '<div class="row" style="color:#94a3b8;">No fee breakdown recorded.</div>'}
          <div class="row" style="margin-top:6px;font-weight:700;"><b>Total Fee:</b> ₹${(parseFloat(f.totalFee)||0).toLocaleString("en-IN")}</div>
          <div class="row"><b>Amount Paid:</b> ₹${(parseFloat(f.paidAmount)||0).toLocaleString("en-IN")}</div>
          <div class="row"><b>Balance Due:</b> ₹${(parseFloat(f.balance)||0).toLocaleString("en-IN")}</div>
          <div class="row" style="color:#64748b;"><b>Date:</b> ${f.paymentDate || "-"} • <b>Method:</b> ${f.paymentMethod || "-"}</div>
        </div>
      `;
      })
      .join("");
    return blocks;
  })();

  const attendanceHtml = (() => {
    if (!attendance.length) return `<div class="box">No attendance records.</div>`;
    const blocks = attendance
      .slice()
      .sort((a, b) => String(b.date).localeCompare(String(a.date)))
      .slice(0, 20)
      .map((a) => `
        <div class="box">
          <div class="row"><b>Date:</b> ${a.date || ""}</div>
          <div class="row"><b>Status:</b> ${a.status || ""}</div>
          ${a.arrivalTime ? `<div class="row"><b>Arrival:</b> ${a.arrivalTime}</div>` : ""}
          ${a.departureTime ? `<div class="row"><b>Departure:</b> ${a.departureTime}</div>` : ""}
        </div>
      `).join("");
    return blocks;
  })();

  const contentHtml = `
    ${profileHtml}
    <h2 style="margin:16px 0 8px 0;">Exams</h2>
    ${examsHtml}
    <h2 style="margin:16px 0 8px 0;">Fees</h2>
    ${feesHtml}
    <h2 style="margin:16px 0 8px 0;">Attendance</h2>
    ${attendanceHtml}
  `;

  const html = buildPrintableHtml("Student Report", contentHtml);
  openPrintWindowOrFallback(html, "Student Report", { autoPrint: true });
}

function getNextId(items) {
  if (!items.length) return 1;
  return Math.max(...items.map(i => Number(i.id) || 0)) + 1;
}

async function addRecord(moduleName, formData) {
  const record = { ...formData };
  if (moduleName === "fees") {
    const total = asNum(record.totalFee);
    const paid = asNum(record.paidAmount);
    const balance = total - paid;
    // Auto-fill paymentDate if missing or empty to ensure it shows on dashboard
    if (!record.paymentDate || String(record.paymentDate).trim() === "") {
      record.paymentDate = todayStr();
    }
    // Only set balance/status if not already correctly set by form submit handler
    if (record.balance === undefined || record.balance === "") {
      record.balance = String(balance);
    }
    if (!record.status) {
      record.status = balance < 0 ? "Advance" : balance === 0 ? "Paid" : paid > 0 ? "Partial" : "Pending";
    }
  }
  if (moduleName === "users") {
    if (!record.password || String(record.password).trim().length < 8) {
      throw new Error("Password is required and must be at least 8 characters long.");
    }
    if (!record.lastLogin) record.lastLogin = nowStr();
    if (!record.status) record.status = "Active";
  }
  await api(`/api/modules/${moduleName}`, { method: "POST", body: JSON.stringify(record) });
  await loadStore();
}

async function removeRecord(moduleName, id) {
  if (moduleName === "fees" && id) {
    const store = getStore();
    const fee = (store.fees || []).find(f => String(f.id) === String(id));
    if (fee && (fee.consolidatedFeeIds || fee.consolidatedDueMgmtIds)) {
      try {
        const feeIds = JSON.parse(fee.consolidatedFeeIds || "[]");
        const mgmtIds = JSON.parse(fee.consolidatedDueMgmtIds || "[]");
        // The backend `server/db-sqlite.js` now handles automatic restoration of dueManagement balances 
        // when a fee record containing consolidatedDueMgmtIds is deleted.
        // We no longer need to manually calculate and send PUT requests from the frontend here.
      } catch (err) {
        console.error("Error reversing consolidation on delete:", err);
      }
    }
  }
  await api(`/api/modules/${moduleName}/${id}`, { method: "DELETE" });

  // Cleanup Face Recognition Data if deleting a student or teacher
  if (moduleName === "students" || moduleName === "teachers") {
    const person = (getStore()[moduleName] || []).find(p => String(p.id) === String(id));
    if (person && person.fullName) {
      const faceStore = getFaceStore();
      const faceKey = `${moduleName}|${person.fullName}`;
      if (faceStore[faceKey]) {
        delete faceStore[faceKey];
        saveFaceStore(faceStore);
        console.log(`[FaceAI] Deleted face data for ${person.fullName}`);
        
        // Try to remove from server as well (best effort)
        try {
          const store = getStore();
          const embeddings = store.faceEmbeddings || [];
          const emb = embeddings.find(e => e.name === person.fullName && e.targetType === moduleName);
          if (emb && emb.id) {
            await api(`/api/modules/faceEmbeddings/${emb.id}`, { method: "DELETE" });
          }
        } catch (e) {
          console.warn("Server face cleanup failed:", e.message);
        }
      }
    }
  }

  await loadStore();
}

// Global alias for inline onclick handlers
window.deleteRecord = removeRecord;

// Global Image Viewer Helpers
window.openImageViewer = function(src, title) {
  const viewer = document.getElementById("imageViewer");
  const img = document.getElementById("imageViewerImg");
  const titleEl = document.getElementById("imageViewerTitle");
  if (!viewer || !img || !titleEl) return;
  
  img.src = src;
  titleEl.textContent = title;
  viewer.classList.remove("hidden");
  document.body.style.overflow = "hidden"; // Prevent background scroll
};

window.closeImageViewer = function() {
  const viewer = document.getElementById("imageViewer");
  if (!viewer) return;
  viewer.classList.add("hidden");
  document.body.style.overflow = ""; // Restore scroll
};

window.currentFeeFilter = window.currentFeeFilter || 'all';

// ═══════════════════════════════════════════════════════════════
// CLASS-WISE FEE & PENDING DUES AGGREGATION ENGINE (100% Real Data)
// ═══════════════════════════════════════════════════════════════
window.getClassWiseFeeStats = function(store) {
  store = store || (typeof getStore === "function" ? getStore() : (window.serverStore || {}));
  const fees = store.fees || [];
  const dueMgmt = store.dueManagement || [];
  const students = store.students || [];

  const studentClassMap = {};
  students.forEach(s => {
    const adm = s.admissionNo || s.admissionno;
    const cls = s.className || s.classname;
    if (adm) studentClassMap[String(adm).trim().toLowerCase()] = cls || 'Unassigned';
  });

  const classMap = {};
  function getClsEntry(rawCls) {
    let c = String(rawCls || '').trim();
    if (!c || c.toLowerCase() === 'null' || c.toLowerCase() === 'undefined') c = 'Unassigned';
    c = c.replace(/^Class\s+/i, '').trim();
    if (!classMap[c]) {
      classMap[c] = {
        className: c,
        totalFee: 0,
        paidFee: 0,
        pendingFee: 0,
        pendingAccounts: new Set(),
        totalStudents: 0
      };
    }
    return classMap[c];
  }

  // Count enrolled students per class
  students.forEach(s => {
    const cls = s.className || s.classname;
    if (cls) getClsEntry(cls).totalStudents++;
  });

  // Aggregate dueManagement (Monthly tuition fees, bus, annual dues)
  dueMgmt.forEach(d => {
    const adm = d.admissionNo || d.admissionno;
    let cls = d.className || d.classname;
    if (!cls && adm) cls = studentClassMap[String(adm).trim().toLowerCase()];
    const entry = getClsEntry(cls);
    const bal = Number(d.balance || d.dueAmount || d.dueamount || 0);
    const paid = Number(d.paidAmount || d.paidamount || 0);
    const st = String(d.status || '').toLowerCase();
    const isUnpaid = st !== 'paid' && bal > 0;

    if (isUnpaid) {
      entry.pendingFee += bal;
      if (adm) entry.pendingAccounts.add(String(adm).trim());
      else if (d.studentName || d.studentname) entry.pendingAccounts.add(String(d.studentName || d.studentname).trim());
    }
    entry.paidFee += paid;
    entry.totalFee += (bal + paid);
  });

  // Aggregate fees table (Fee receipts & outstanding balances)
  fees.forEach(f => {
    const st = String(f.status || '').toLowerCase();
    if (st === 'merged') return; // Skip merged records to prevent double-counting in billed total

    const adm = f.admissionNo || f.admissionno;
    let cls = f.className || f.classname;
    if (!cls && adm) cls = studentClassMap[String(adm).trim().toLowerCase()];
    const entry = getClsEntry(cls);
    const bal = Number(f.balance || 0);
    const paid = Number(f.paidAmount || f.paidamount || 0);
    const isUnpaid = st !== 'paid' && bal > 0;

    if (isUnpaid) {
      entry.pendingFee += bal;
      if (adm) entry.pendingAccounts.add(String(adm).trim());
      else if (f.studentName || f.studentname) entry.pendingAccounts.add(String(f.studentName || f.studentname).trim());
    }
    entry.paidFee += paid;
    const recTot = Math.max(bal + paid, Number(f.tuitionFee || f.tuitionfee || f.totalFee || f.totalfee || 0));
    entry.totalFee += recTot;
  });

  // Ensure totalFee reflects at least all pending + paid amounts
  Object.values(classMap).forEach(entry => {
    if (entry.totalFee < entry.pendingFee + entry.paidFee) {
      entry.totalFee = entry.pendingFee + entry.paidFee;
    }
  });

  const classOrderRank = (clsName) => {
    const raw = String(clsName || '').trim();
    const base = raw.split(/[-\s]/)[0].toUpperCase();
    const map = {
      'NURSERY': 1, 'NUR': 1,
      'LKG': 2, 'L.K.G': 2,
      'UKG': 3, 'U.K.G': 3,
      'I': 4, '1': 4,
      'II': 5, '2': 5,
      'III': 6, '3': 6,
      'IV': 7, '4': 7,
      'V': 8, '5': 8,
      'VI': 9, '6': 9,
      'VII': 10, '7': 10,
      'VIII': 11, '8': 11,
      'IX': 12, '9': 12,
      'X': 13, '10': 13,
      'XI': 14, '11': 14,
      'XII': 15, '12': 15
    };
    return map[base] !== undefined ? map[base] : 99;
  };

  const sorted = Object.values(classMap)
    .filter(x => x.className !== 'Unassigned' || (x.totalFee > 0 || x.pendingFee > 0))
    .sort((a, b) => {
      const rA = classOrderRank(a.className);
      const rB = classOrderRank(b.className);
      if (rA !== rB) return rA - rB;
      return a.className.localeCompare(b.className);
    });

  let grandTotalFee = 0;
  let grandTotalPending = 0;
  let grandTotalPaid = 0;
  const allPendingSet = new Set();

  sorted.forEach(c => {
    grandTotalFee += c.totalFee;
    grandTotalPending += c.pendingFee;
    grandTotalPaid += c.paidFee;
    c.pendingAccounts.forEach(adm => allPendingSet.add(adm));
  });

  return {
    classes: sorted,
    grandTotalFee,
    grandTotalPending,
    grandTotalPaid,
    grandTotalPendingAccounts: allPendingSet.size
  };
};

window.filterDuesByClass = function(clsName) {
  const modal = document.getElementById("classWiseFeeModal");
  if (modal) modal.remove();

  if (typeof window.navigateModule === "function") {
    window.navigateModule("dueManagement");
  } else {
    const btn = document.querySelector('button[data-module="dueManagement"]');
    if (btn) btn.click();
  }

  setTimeout(() => {
    const cf = document.getElementById("classFilter");
    if (cf) {
      cf.value = clsName;
      cf.dispatchEvent(new Event("change"));
    }
  }, 250);
};

// ═══════════════════════════════════════════════════════════════
// UNIVERSAL HORIZONTAL & DRAG SCROLL ENGINE
// ═══════════════════════════════════════════════════════════════
window.makeHorizontallyScrollable = function(container) {
  if (!container || container._hasHScrollInit) return;
  container._hasHScrollInit = true;

  // 1. Mouse wheel translation: vertical mouse wheel -> horizontal scroll
  container.addEventListener('wheel', function(e) {
    if (e.deltaY !== 0 && container.scrollWidth > container.clientWidth) {
      e.preventDefault();
      container.scrollLeft += (e.deltaY * 1.2);
    }
  }, { passive: false });

  // 2. Mouse Drag-to-Scroll (Desktop grab and drag)
  let isDown = false;
  let startX;
  let scrollLeft;

  container.style.cursor = 'grab';
  container.addEventListener('mousedown', function(e) {
    if (e.target.tagName === 'BUTTON' || e.target.closest('button') || e.target.closest('a')) return;
    isDown = true;
    container.style.cursor = 'grabbing';
    container.style.userSelect = 'none';
    startX = e.pageX - container.offsetLeft;
    scrollLeft = container.scrollLeft;
  });

  const stopDrag = function() {
    isDown = false;
    container.style.cursor = 'grab';
    container.style.removeProperty('user-select');
  };

  container.addEventListener('mouseleave', stopDrag);
  container.addEventListener('mouseup', stopDrag);

  container.addEventListener('mousemove', function(e) {
    if (!isDown) return;
    e.preventDefault();
    const x = e.pageX - container.offsetLeft;
    const walk = (x - startX) * 1.5;
    container.scrollLeft = scrollLeft - walk;
  });
};

