  const doc = new window.jspdf.jsPDF('landscape');
  doc.text(`${moduleConfig[currentModule].title} Report`, 14, 14);
  doc.autoTable({ head: [columns.map(toLabel)], body, startY: 22, styles: { fontSize: 7, cellPadding: 2 } });
