        (r.admissionNo || "").toLowerCase().includes(q) ||
        (r.phone || "").toLowerCase().includes(q) ||
        (r.address || "").toLowerCase().includes(q) ||
        (r.fatherName || r.parentName || "").toLowerCase().includes(q)
